// EDIT THIS if your site's items don't fit the default description below
const EXTRACTION_CRITERIA = "Extract each relevant listing item found on the page (e.g. each ad, product, job posting, auction lot, property - depending on the monitored site).";

const raw = $input.first().json.data || '';
let html = String(raw);
html = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ');

// character limit to control token cost - increase if the page is large and items are getting missed
const MAX_CHARS = 100000;
if (html.length > MAX_CHARS) html = html.slice(0, MAX_CHARS);

const systemText = "You are an assistant that extracts structured listings from web pages based on raw HTML. " + EXTRACTION_CRITERIA + " For each item, extract: title, description (short summary), link (full URL - use the href found in the HTML; if relative, keep it as-is), date (if available, otherwise leave empty). Return ONLY a JSON array, no extra text, no markdown, no code blocks, using exactly these field names: title, description, link, date. If you find no items, return an empty array [].";

const userText = "PAGE HTML:\n" + html;

const requestBody = {
  model: 'claude-haiku-4-5',
  max_tokens: 8000,
  system: [ { type: 'text', text: systemText } ],
  messages: [ { role: 'user', content: userText } ]
};

return [{ json: { requestBody } }];

let items = [];
try {
  const resp = $input.first().json;
  const blocks = resp.content || [];
  const textBlock = blocks.find(b => b && b.type === 'text');
  let text = textBlock ? textBlock.text : '';
  text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  const parsed = JSON.parse(text);
  items = Array.isArray(parsed) ? parsed : [];
} catch (e) {
  items = [];
}
return items.map(v => ({ json: v }));

// EDIT THIS: describe in plain English what you consider relevant
const CRITERIA_TEXT = "Describe here what you consider relevant. Example: 'I'm looking for a 2 or 3 bedroom apartment in the Porto area, appraisal value under 150,000 euros, preferably unoccupied and with no condo debts mentioned in the auction notice.'";

const SYSTEM_TEXT = "You are an assistant that evaluates whether an item found on a web page is relevant according to the user's criteria.\n\nUSER CRITERIA:\n" + CRITERIA_TEXT;

return $input.all().map(item => {
  const v = item.json;

  const userText = "ITEM:\n" +
    "Title: " + (v.title || '') + "\n" +
    "Description: " + (v.description || '') + "\n" +
    "Link: " + (v.link || '') + "\n\n" +
    "Evaluate this item's compatibility with the user's criteria. Return ONLY a JSON in the following format, no extra text, no markdown, no code blocks:\n" +
    "{\n" +
    "  \"score\": (rating from 0 to 10, number),\n" +
    "  \"short_justification\": \"1-2 sentences explaining the score\"\n" +
    "}";

  const requestBody = {
    model: 'claude-haiku-4-5',
    max_tokens: 300,
    system: [ { type: 'text', text: SYSTEM_TEXT, cache_control: { type: 'ephemeral' } } ],
    messages: [ { role: 'user', content: userText } ]
  };

  return { json: { item: v, requestBody } };
});

const originals = $('Build AI Request (Score)').all();
const responses = $input.all();
const result = [];

for (let i = 0; i < responses.length; i++) {
  const original = (originals[i] && originals[i].json && originals[i].json.item) || {};
  const resp = responses[i].json;

  let scoreData = { score: null, short_justification: 'Error processing AI response.' };

  try {
    const blocks = resp.content || [];
    const textBlock = blocks.find(b => b && b.type === 'text');
    let text = textBlock ? textBlock.text : '';
    text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
    const parsed = JSON.parse(text);
    scoreData = {
      score: typeof parsed.score === 'number' ? parsed.score : null,
      short_justification: parsed.short_justification || ''
    };
  } catch (e) {}

  result.push({ json: Object.assign({}, original, scoreData) });
}

return result;

function esc(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const approved = $input.all().map(i => i.json);

const blocks = approved.map(v => {
  return (
    '<div style="border:1px solid #ddd;border-radius:8px;padding:16px;margin-bottom:20px;">' +
    '<h3 style="margin:0 0 4px;">' + esc(v.title) + '</h3>' +
    '<p style="margin:0 0 8px;color:#555;">Score: <b>' + esc(v.score) + '</b>/10</p>' +
    '<p><b>Why it is relevant:</b> ' + esc(v.short_justification) + '</p>' +
    '<p>' + esc(v.description) + '</p>' +
    '<p><a href="' + esc(v.link) + '">View original item</a></p>' +
    '</div>'
  );
}).join('');

const html = '<h2>AI Site Monitor - Results (' + approved.length + (approved.length === 1 ? ' item' : ' items') + ')</h2>' + blocks;

return [{ json: { total_approved: approved.length, summary_html: html } }];
